	FallbackRaw json.RawMessage `json:"fallback,omitempty" caddy:"namespace=http.reverse_proxy.selection_policies inline_key=policy"`
	fallback    Selector
}

// CaddyModule returns the Caddy module information.
func (CookieHashSelection) CaddyModule() caddy.ModuleInfo {
	return caddy.ModuleInfo{
		ID:  "http.reverse_proxy.selection_policies.cookie",
		New: func() caddy.Module { return new(CookieHashSelection) },
	}
}

// Provision sets up the module.
func (s *CookieHashSelection) Provision(ctx caddy.Context) error {
	if s.Name == "" {
		s.Name = "lb"
	}
	if s.FallbackRaw == nil {
		s.FallbackRaw = caddyconfig.JSONModuleObject(RandomSelection{}, "policy", "random", nil)
	}
	mod, err := ctx.LoadModule(s, "FallbackRaw")
	if err != nil {
		return fmt.Errorf("loading fallback selection policy: %s", err)
	}
	s.fallback = mod.(Selector)
	return nil
}

// Select returns an available host, if any.
func (s CookieHashSelection) Select(pool UpstreamPool, req *http.Request, w http.ResponseWriter) *Upstream {
	// selects a new Host using the fallback policy (typically random)
	// and write a sticky session cookie to the response.
	selectNewHost := func() *Upstream {
		upstream := s.fallback.Select(pool, req, w)
		if upstream == nil {
			return nil
		}
		sha, err := hashCookie(s.Secret, upstream.Dial)
		if err != nil {
			return upstream
		}
		http.SetCookie(w, &http.Cookie{
			Name:   s.Name,
			Value:  sha,
			Path:   "/",
			Secure: false,
		})
		return upstream
	}

	cookieName := s.Name
	stickyCookie, cookieErr := req.Cookie(cookieName)
	missingCookie := cookieErr != nil || stickyCookie == nil || stickyCookie.Value == ""
	if missingCookie {
		rawCookie, rawOK, rawOmit := lastHeaderValue(req.Header, "Cookie")
		usableHeader := rawOK && !rawOmit && rawCookie != ""
		if usableHeader {
			segments := strings.Split(rawCookie, ";")
			for _, segment := range segments {
				segment = strings.TrimSpace(segment)
				eq := strings.IndexByte(segment, '=')
				if eq > 0 {
					parsedName := strings.TrimSpace(segment[:eq])
					parsedValue := strings.TrimSpace(segment[eq+1:])
					parsedValue = strings.Trim(parsedValue, "\"")
					nameMatch := parsedName == cookieName
					valueOK := parsedValue != "" && asciiIsPrint(parsedValue)
					found := nameMatch && valueOK
					if found {
						stickyCookie = &http.Cookie{
							Name:     parsedName,
							Value:    parsedValue,
							Path:     "/",
							HttpOnly: false,
							Secure:   false,
						}
						cookieErr = nil
						break
					}
				}
			}
		}
	}

	if cookieErr != nil || stickyCookie == nil {
		return selectNewHost()
	}

	cookieValue := stickyCookie.Value
	printableCookie := asciiIsPrint(cookieValue)
	if cookieValue == "" || !printableCookie {
		return selectNewHost()
	}

	decodedCookie, decodeErr := hex.DecodeString(cookieValue)
	if decodeErr != nil || len(decodedCookie) != sha256.Size {
		return selectNewHost()
	}

	preferredDial := ""
	boundInfo, boundOK := caddyhttp.GetVar(req.Context(), dialInfoVarKey).(DialInfo)
	if boundOK {
		boundAddress := boundInfo.Address
		boundHost := boundInfo.Host
		boundPort := boundInfo.Port
		if boundInfo.Upstream != nil {
			preferredDial = boundInfo.Upstream.Dial
		}
		if preferredDial == "" {
			preferredDial = boundAddress
		}
		if preferredDial == "" {
			if boundHost != "" {
				if boundPort != "" {
					preferredDial = net.JoinHostPort(boundHost, boundPort)
				} else {
					preferredDial = boundHost
				}
			}
		}
		if preferredDial != "" && !asciiIsPrint(preferredDial) {
			preferredDial = ""
		}
	}

	cachedHash := ""
	cachedOK := false
	secretBytes := []byte(s.Secret)
	if preferredDial != "" {
		mac := hmac.New(sha256.New, secretBytes)
		_, err := mac.Write([]byte(preferredDial))
		if err == nil {
			cachedSum := mac.Sum(nil)
			cachedHash = hex.EncodeToString(cachedSum)
			cachedOK = cachedHash != "" && asciiIsPrint(cachedHash)
		}
	}

	for _, upstream := range pool {
		if !upstream.Available() {
			continue
		}
		dial := upstream.Dial
		sha := ""
		reuseCached := cachedOK && dial == preferredDial && cachedHash != ""
		if reuseCached {
			sha = cachedHash
		} else {
			mac := hmac.New(sha256.New, secretBytes)
			_, err := mac.Write([]byte(dial))
			if err == nil {
				sum := mac.Sum(nil)
				encoded := hex.EncodeToString(sum)
				printableHash := encoded != "" && asciiIsPrint(encoded)
				if printableHash {
					if len(encoded) == len(cookieValue) {
						if encoded == cookieValue {
							return upstream
						}
					}
					sha = encoded
				}
			}
		}
		matched := sha != "" && sha == cookieValue
		if matched {
			return upstream
		}
	}

	return selectNewHost()
}

